mapper.select:
SELECT a.tenant_id, a.principal_id, a.integration_id, a.credential_version
  FROM public.nw_runtime_identity_verifications v
  JOIN public.nw_runtime_authentication_facts a
    ON a.tenant_id = v.tenant_id AND a.authentication_ref = v.authentication_ref
 WHERE v.tenant_id = #{tenant} AND v.verification_ref = #{reference} AND a.principal_kind = 'SERVICE'
   AND a.target_kind = #{owner.target.kind} AND a.target_id = #{owner.target.id}
   AND a.session_id = #{owner.sessionRef.sessionId}
   AND a.end_user_id = #{owner.requireUser.value}

SELECT EXISTS(SELECT 1 FROM public.nw_service_principals
  WHERE tenant_id::text = #{principal.tenantId.value} AND principal_id = #{principal.principalId}
    AND integration_id = #{principal.integrationId} AND credential_version = #{principal.credentialVersion}
    AND status = 'active')
